payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
html=r'''<!doctype html><html lang="tr" dir="ltr"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>LarenLex Android • L4 tüm uygulama</title>
<style>
:root{color-scheme:light;--ink:#18304b;--navy:#152b43;--gold:#b58b4b;--muted:#54687f;--border:#dce4e9;--bg:#f5f7f9;--card:#fff;--focus:#147eb3;--danger:#803c2e;font-family:system-ui,-apple-system,"Segoe UI",Arial,sans-serif;font-size:16px;line-height:1.52}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink)}button,select,input{font:inherit}button{cursor:pointer;min-height:46px}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid var(--focus);outline-offset:2px}a{color:#0e537e}header{background:var(--navy);color:white;padding:18px max(18px,calc((100vw - 1180px)/2)) 21px}.overline{color:#f2d3a1;letter-spacing:.1em;text-transform:uppercase;font-size:12px;font-weight:700}h1{font-size:clamp(24px,3.5vw,34px);margin:5px 0 6px;line-height:1.2}header p{margin:0;color:#dce6f0;max-width:780px}header .indicator{margin-top:12px;color:#fff;background:#38506a;border-inline-start:4px solid var(--gold);padding:10px 13px;border-radius:5px;font-size:13px}main{max-width:1180px;padding:18px;margin:auto;display:grid;grid-template-columns:minmax(220px,250px) minmax(0,1fr);gap:18px}aside,.panel,.tile{background:var(--card);border:1px solid var(--border);border-radius:12px}aside{padding:14px;align-self:start;position:sticky;top:12px}.brand{font-size:15px;font-weight:700;padding:8px;color:var(--navy)}.nav{display:grid;gap:5px}.nav button{background:transparent;color:var(--ink);text-align:start;border:0;border-radius:7px;padding:10px 12px;font-weight:600}.nav button:hover,.nav button[aria-current=page]{background:#e9f0f4}.nav button[aria-current=page]{border-inline-start:3px solid var(--gold)}.lang{margin:16px 3px 6px}.lang label{display:block;font-weight:650;margin-bottom:6px}.lang select{width:100%;padding:10px;border:1px solid #8aa0b4;border-radius:8px;background:white;color:var(--ink)}.main{min-width:0}.hero{margin-bottom:14px}.hero h2{font-size:23px;line-height:1.25;margin:0 0 6px}.hero p{color:var(--muted);margin:0}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-bottom:15px}.stat{padding:13px;background:#ecf1f4;border:1px solid #dce5eb;border-radius:8px}.stat strong{font-size:22px;display:block}.stat span{font-size:12px;color:var(--muted)}.panel{padding:18px;margin-bottom:14px}.panel h3{margin:0 0 11px;font-size:19px}.tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.tile{padding:14px;min-width:0;display:flex;flex-direction:column;gap:5px;box-shadow:0 3px 12px rgba(21,43,67,.035)}.tile h3{margin:0;font-size:16px}.tile p{margin:0;font-size:13px;color:var(--muted)}.tile small,.status{font-size:12px;color:#785928;font-weight:650}.tile button,.inline-button{margin-top:6px;border:1px solid #becbd6;color:var(--navy);background:#f8fafb;border-radius:7px;padding:7px 10px;min-height:42px;text-align:start}.tile button:disabled,.inline-button:disabled{cursor:not-allowed;color:#536475;background:#e9edef}.subgrid{display:grid;gap:8px}.subitem{padding:10px 12px;background:#f7f9fb;border:1px solid var(--border);border-radius:8px}.subitem p{margin:5px 0 0;color:var(--muted);font-size:13px}.warning{border-inline-start:4px solid var(--gold);background:#fbf8ef;padding:12px 14px;margin:0 0 13px;border-radius:6px}.warning strong{display:block}.term{overflow-wrap:anywhere;unicode-bidi:isolate;direction:ltr}.bad{color:var(--danger);font-weight:700}.field{margin:9px 0}.field label{display:block;font-weight:650;margin-bottom:5px}.field select{width:100%;border:1px solid #8aa0b4;border-radius:7px;padding:10px;background:white}.out{white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f3f6;padding:13px;border-radius:8px;font-size:14px}.badge{display:inline-block;background:#f7ead5;border-radius:999px;padding:2px 9px;font-weight:650;font-size:12px;color:#6f511f}.hide{display:none!important}.detail p{margin:6px 0 12px}.foot{padding:22px 18px;color:var(--muted);text-align:center;font-size:12px}.rtl .term{direction:ltr;unicode-bidi:isolate}@media(max-width:800px){main{display:block;padding:12px}aside{position:static;margin-bottom:14px}.nav{grid-template-columns:repeat(3,minmax(0,1fr))}.nav button{font-size:13px;padding:8px}.tiles{grid-template-columns:1fr 1fr}}@media(max-width:520px){header{padding:16px}main{padding:10px}.stats{grid-template-columns:repeat(2,1fr)}.tiles{grid-template-columns:1fr}.nav{grid-template-columns:repeat(2,1fr)}.panel{padding:13px}h1{font-size:24px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}
</style></head><body>
<header><div class="overline">LarenLex · Android L4</div><h1 id="banner">Bütün uygulama · Hukukî çalışma ve belge akışları</h1><p id="tagline">14 modül · 17 hizmet · 14 kitle · 12 sorun rotası için kaynak kontrolü · 6 dil</p><div class="indicator" role="status">ÇEVRİMDIŞI TASARIM ÖNİZLEMESİ: Hukukî hizmet, resmî başvuru, ödeme ve gerçek müşteri verisi işlemleri açık değildir. Bu ekran gerçek APK değildir.</div></header>
<main><aside><div class="brand">LarenLex / L4</div><nav class="nav" aria-label="Bölümler" id="navigation"></nav><div class="lang"><label for="language">Dil / Language / اللغة</label><select id="language"><option value="tr">Türkçe</option><option value="nl">Nederlands</option><option value="de">Deutsch</option><option value="en">English</option><option value="ar">العربية</option><option value="ru">Русский</option></select></div><p class="warning" id="translation-caveat">Hukukî içerik yalnız Türkçe kaynak metnidir; diğer dillerin hukukî çevirileri insan incelemesinden geçmemiştir.</p></aside>
<section class="main"><div class="hero"><h2 id="heading">Modüller</h2><p id="description">Bir ana sistemi seçin. Görünen katalog, canlı hizmet yetkisi anlamına gelmez.</p></div><div class="stats"><div class="stat"><strong>14</strong><span>ana sistem</span></div><div class="stat"><strong>453</strong><span>işlev kimliği</span></div><div class="stat"><strong>17</strong><span>hizmet</span></div><div class="stat"><strong>6</strong><span>taslak arayüz dili</span></div></div><div class="panel" id="main-panel"><h3 id="panel-title">Katalog</h3><div id="content" aria-live="polite"></div></div><div class="panel"><h3 id="assurance">Hukukî ve teknik sınır</h3><p class="warning">Özgün 12 sorun rotasının kimlikleri, bazı rehber/kurumsal içerik kaynakları ve insan/kurum onayları eksiktir. Varsayılan durum kapalıdır. Hizmet sayfasının görünmesi, yetkili temsil, ücret tahsilatı veya gerçek başvuru anlamına gelmez.</p><p id="boundary">Dijital kurum adapter'ları, resmî gönderim, gerçek makbuz, ödeme ve kimlik oturumu devre dışı. İçeriğin güncelliği uzman onayı gerektirir.</p></div></section></main><div class="foot">LarenLex Android L4 · Kanonik kaynak: LARENLEX_ANDROID_TEKIL_ANA_TALIMATNAME.md · Tasarım/işlem kabul ayrıdır.</div>
<script id="catalog" type="application/json">__CATALOG__</script>
<script>(()=>{'use strict';const D=JSON.parse(document.getElementById('catalog').textContent);const $=id=>document.getElementById(id);const keys=['modules','services','audiences','issues','guides','staff','documents','institutions','privacy'];let locale='tr',section='modules';const t=k=>D.ui_translations_unreviewed[locale][k]||k;const sourceText=(name)=>name===undefined||name===null?'Özgün kaynak başlığı bekleniyor':String(name);const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=String(text);return n};const clear=()=> $('content').replaceChildren();const add=(node)=>$('content').append(node);const notice=(s)=>add(el('p','warning',s));function btn(text,callback){let b=el('button','inline-button',text);b.type='button';b.addEventListener('click',callback);return b;}function card(title,description,callback,status){const card=el('article','tile');card.append(el('h3','',title));card.append(el('p','',description));if(status)card.append(el('small','',status));if(callback)card.append(btn('Ayrıntıyı aç',callback));return card;}function grid(items){const root=el('div','tiles');items.forEach(x=>root.append(x));add(root)}function detail(title,body,code){clear();add(btn('‹ '+t('back'),()=>render(section)));add(el('h3','',title));if(code){const p=el('p','term',code);p.dir='ltr';add(p);}add(el('p','',body));notice(t('review')+' · '+t('blocked')+' · Bağımsız kabul yok.');}function render(sectionName){section=sectionName;document.querySelectorAll('#navigation button').forEach(b=>b.setAttribute('aria-current',b.dataset.key===section?'page':'false'));$('heading').textContent=t(section==='modules'?'module':section);$('panel-title').textContent=t(section==='modules'?'module':section);$('description').textContent=t('preview')+' · '+t('review');clear();if(section==='modules'){grid(D.modules.map(m=>card(m.id+' · '+m.title,m.groups.length+' alt grup · '+m.groups.reduce((n,g)=>n+g.features.length,0)+' işlev',()=>moduleDetail(m),'Katalog · kabul yok')));return;}if(section==='services'){grid(D.services.map(s=>card(s.title_tr,s.description_tr,()=>detail(s.title_tr,s.description_tr+' Ülke/meslekî yetki ve ücret teyit edilmedi.',s.id+' · '+s.slug_reference_only),'Ön inceleme / erişim kapalı')));return;}if(section==='audiences'){notice('Bu 14 slug tarihî portal kaynaklarında geçen referanslardır; portal kodu ya da aktif hizmet rotası değildir.');grid(D.audiences.map(a=>card(a.title_tr,'Ülke, profesyonel kapsam ve hizmet eşlemesi doğrulanmadı.',()=>detail(a.title_tr,'Çoktan çoğa hizmet bağlantısı yetki ve kaynak incelemesi sonrasında açılır.',a.historic_portal_slug_reference_only),'Kanonik kitle · yayın kapalı')));return;}if(section==='issues'){notice('12 özgün sorun rotasının tam ID/slug kayıtları erişilebilir LarenLex kaynaklarında bulunamadı. Yeni slug üretilmedi.');grid(D.issue_routes.map(i=>card('Sorun rotası '+i.slot,'Kaynak ID, başlık ve hizmet eşlemesi bekliyor.',()=>detail('Sorun rotası '+i.slot,'Özgün v18 kaynak tanımı olmadan otomatik yönlendirme yapılmaz.','ISSUE SLOT '+i.slot),'Kanonik kayıt yok')));return;}if(section==='guides'){for(const [k,v] of Object.entries(D.content)){const item=el('div','subitem');item.append(el('strong','',({guides:'Rehberler',corporate_pages:'Kurumsal sayfalar',document_lists:'Belge listeleri'})[k]+' · '+v.length));item.append(el('p','','Başlık, kaynak URL, uzman onayı ve güncellik bekleniyor. Eski form güncel sayılmaz.'));add(item);}return;}if(section==='staff'){grid(D.staff.map(s=>card(s.id,'Dosya ve tenant kapsamı, MFA ve yazma izni doğrulanmadı.',()=>detail(s.id,'Yetki yalnız görünür sekmeye göre verilmez. Gerçek kayıt okuma/yazma kapalıdır.','STAFF / '+s.id),'Okuma/yazma kapalı')));return;}if(section==='documents'){documentPanel();return;}if(section==='institutions'){institutionPanel();return;}if(section==='privacy'){notice('Gerçek müşteri verisi, kimlik/oturum, sınır ötesi aktarım ve özel nitelikli dosya işleme kapalıdır.');add(el('p','','Veri sorumlusu, saklama takvimi, DPIA, DPA, erişim günlükleri ve DSAR kapsamı uzman tarafından onaylanmadan işlem açılmaz.'));return;}}
function moduleDetail(m){clear();add(btn('‹ '+t('back'),()=>render('modules')));add(el('h3','',m.id+' · '+m.title));for(const g of m.groups){const b=el('div','subitem');b.append(el('strong','',g.id+' · '+g.title+' · '+g.features.length+' işlev'));b.append(btn('İşlevleri göster',()=>{clear();add(btn('‹ '+t('back'),()=>moduleDetail(m)));add(el('h3','',g.title));const subs=el('div','subgrid');g.features.forEach(f=>subs.append(card(f.id,f.title,()=>detail(f.title,'Kaynak işlev tanımı korunmuştur. Fiilen sağlanan hizmet ve bağımsız kabul değildir.',f.id),'Bağımsız kabul yok')));add(subs)}));add(b)}}
function docField(root,id,label,values){let wrapper=el('div','field');let lb=el('label','',label);lb.htmlFor=id;let sel=el('select');sel.id=id;for(const [value,title] of values){let op=el('option','',title);op.value=value;sel.append(op);}wrapper.append(lb,sel);root.append(wrapper);return sel;}function documentPanel(){notice('Yalnız boş örnek şablon doğrulaması. Kişisel veri girmeyin, gerçek dilekçe/başvuru oluşturulmaz.');const root=el('div','');const country=docField(root,'country','Ülke',[['','Ülke seçilmedi'],['NL','Hollanda'],['DE','Almanya'],['TR','Türkiye']]);const authority=docField(root,'authority','İlgili merci',[['','Merci teyit edilmedi'],['COURT','Mahkeme (uzman incelemesi şart)'],['IND','IND (G1–G4 zorunlu)']]);const matter=docField(root,'topic','Belge konusu',[['','Konu seçilmedi'],['REQUEST','Bilgi talebi (taslak)'],['OBJECTION','İtiraz (özel süre/uzman incelemesi)']]);const proof=docField(root,'proof','Zorunlu delil durumu',[['','Henüz incelenmedi'],['INCOMPLETE','Eksik'],['REVIEW','Uzman incelemesi bekliyor']]);const output=el('p','out','Belge durumu: TASLAK');const b=btn('Koşullu alanları kontrol et',()=>{const values=[country.value,authority.value,matter.value,proof.value];output.textContent=values.every(Boolean)?'Durum: UZMAN İNCELEMESİ BEKLİYOR. Resmî gönderim, makbuz ve dosya dışa aktarımı YOK.':'Durum: EKSİK TASLAK. Ülke, merci, konu ve delil incelemesi gerekir.';});root.append(b,output);add(root);}
function institutionPanel(){notice('IND ve mahkeme işlemleri yalnız hazırlık düzeyindedir. Bir başvurunun gönderildiği ya da bir makbuz alındığı iddia edilmez.');for(const type of ['ind_procedures','ind_gates','judicial_tasks']){const head=el('h3','',type+' · '+D[type].length);add(head);const gridEl=el('div','subgrid');D[type].forEach(x=>{const item=el('div','subitem');const id=el('b','term',x.id);id.dir='ltr';item.append(id,el('p','',x.title_tr));gridEl.append(item)});add(gridEl);}add(el('h3','','Resmî bilgi kaynakları'));for(const item of D.institutions){const div=el('div','subitem');div.append(el('strong','',item.name));let p=el('p','',item.url);p.className='term';p.dir='ltr';div.append(p,el('p','','Kaynak bağlantısı bilgilendirme içindir; kurum API çağrısı yapılmaz. Son hukukî onay yok.'));add(div);}}
function updateLanguage(){locale=$('language').value;document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';document.body.classList.toggle('rtl',locale==='ar');$('translation-caveat').textContent=locale==='tr'?'Hukukî içerik yalnız Türkçe kaynak metnidir; diğer dillerin hukukî çevirileri insan incelemesinden geçmemiştir.':'Interface translation is draft only. Legal content remains in source Turkish pending human translation review.';document.querySelectorAll('#navigation button').forEach(b=>b.textContent=t(b.dataset.key==='modules'?'module':b.dataset.key));render(section)}keys.forEach(key=>{const b=el('button','',t(key==='modules'?'module':key));b.type='button';b.dataset.key=key;b.addEventListener('click',()=>render(key));$('navigation').append(b)});$('language').addEventListener('change',updateLanguage);render('modules');})();</script></body></html>'''
html=html.replace('__CATALOG__',payload)
out=ROOT/'preview/LARENLEX_L4_BUTUN_UYGULAMA_ETKILESIMLI_ONIZLEME.html'
out.write_text(html,encoding='utf-8')
print('preview',out, 'bytes',out.stat().st_size)
